function arenaLayout(g){const thin=g.w<800?31:36,side=g.w*.125;
const layouts=[
[{x:.18,y:.26,w:.16},{x:.65,y:.26,w:.16},{x:.28,y:.68,w:.16},{x:.56,y:.68,w:.16},{x:.12,y:.48,w:.10},{x:.78,y:.48,w:.10}],
[{x:.19,y:.29,w:.14},{x:.59,y:.21,w:.16},{x:.25,y:.68,w:.16},{x:.68,y:.64,w:.13},{x:.12,y:.50,w:.10},{x:.76,y:.43,w:.12}],
[{x:.25,y:.24,w:.15},{x:.65,y:.34,w:.16},{x:.19,y:.63,w:.15},{x:.59,y:.71,w:.16},{x:.10,y:.44,w:.10},{x:.79,y:.54,w:.10}]
];return layouts[MAPS.indexOf(g.map)].map(b=>({x:b.x*g.w,y:b.y*g.h,w:b.w*g.w,h:thin}))}
function initialiseChallenge(g){g.tier=g.hero.rank;g.maxAmmo=g.hero.maxAmmo;g.attackPower=g.hero.damage;g.monsterBonus=2*(g.tier-1);g.monsterDamage=1+Math.floor((g.tier-1)/4);g.dashCooldown=0;g.dashRemaining=0;g.facing={x:0,y:-1};g.hazards=[];g.hazardClock=10;g.walls=arenaLayout(g);g.field=paintField(g);$('#arena-subtitle').textContent=(g.subject==='mixed'?'All-rounder mix':SUBJECTS.find(s=>s.id===g.subject).name)+' · '+g.map.name+' · Rank '+g.tier}
function dash(){const g=game;if(!g||g.paused||g.dashCooldown>0)return;let x=+!!(keys.ArrowRight||keys.d)-+!!(keys.ArrowLeft||keys.a),y=+!!(keys.ArrowDown||keys.s)-+!!(keys.ArrowUp||keys.w);if(stick.pointerId!==null){x=stick.x;y=stick.y}const d=Math.hypot(x,y);if(d>.05)g.facing={x:x/d,y:y/d};GameAudio.effect('dash');g.dashRemaining=.18;g.dashCooldown=4;g.invincible=Math.max(g.invincible,.24);burst(g.x,g.y,g.map.accent,8)}
function updateChallenge(g,dt){g.dashCooldown=Math.max(0,g.dashCooldown-dt);g.dashRemaining=Math.max(0,g.dashRemaining-dt);g.hazardClock-=dt;if(g.hazardClock<=0){GameAudio.effect('warning');g.hazards.push({x:g.x,y:g.y,age:0,fired:false,r:58});g.hazardClock=g.mode.id==='expert'?7:Math.max(8,12-g.tier*.35)}for(const h of g.hazards){h.age+=dt;if(h.age>=1.4&&!h.fired){h.fired=true;if(Math.hypot(g.x-h.x,g.y-h.y)<h.r+22)damagePlayer(g);burst(h.x,h.y,'#ffd7a3',16)}}g.hazards=g.hazards.filter(h=>h.age<1.85);const dashLabel=g.dashCooldown>0?Math.ceil(g.dashCooldown)+'s':'READY';if(g.lastDashLabel===dashLabel)return;g.lastDashLabel=dashLabel;const label=$('#dash-cooldown');if(label)label.textContent=g.dashCooldown>0?Math.ceil(g.dashCooldown)+'s':'READY';const button=document.querySelector('.dash-button');if(button){button.classList.toggle('ready',g.dashCooldown<=0);button.setAttribute('aria-label',g.dashCooldown>0?'Dodge dash ready in '+Math.ceil(g.dashCooldown)+' seconds':'Dodge dash ready. Keyboard: Shift.')}}
function renderHazards(c,g){for(const h of g.hazards){c.save();c.translate(h.x,h.y);c.fillStyle=h.fired?'#ffce9655':'#ff916026';c.strokeStyle=h.fired?'#ffe0a5':'#ffcb86';c.lineWidth=3;c.setLineDash(h.fired?[]:[8,6]);c.beginPath();c.arc(0,0,h.r,0,7);c.fill();c.stroke();c.setLineDash([]);if(!h.fired){c.strokeStyle='#fff3c0';c.lineWidth=5;c.beginPath();c.arc(0,0,h.r-7,-Math.PI/2,-Math.PI/2+Math.PI*2*Math.min(1,h.age/1.4));c.stroke();c.fillStyle='#fff4d9';c.strokeStyle='#654e4b';c.lineWidth=3;c.textAlign='center';c.font='900 13px sans-serif';c.strokeText('MOVE!',0,5);c.fillText('MOVE!',0,5)}c.restore()}if(g.dashRemaining>0){c.strokeStyle=g.map.accent+'aa';c.lineWidth=8;c.lineCap='round';c.beginPath();c.moveTo(g.x-g.facing.x*55,g.y-g.facing.y*55);c.lineTo(g.x,g.y);c.stroke()}}
